-- 1. inspection_charges de teste
DELETE FROM inspection_charges 
WHERE LOWER(client_email) LIKE '%test%' OR LOWER(vessel_name) LIKE '%test%';

-- 2. fuel_records de teste
DELETE FROM fuel_records 
WHERE LOWER(vessel_name) LIKE '%test%' OR LOWER(client_email) LIKE '%test%';

-- 3. inspections de teste
DELETE FROM inspections 
WHERE LOWER(vessel_name) LIKE '%test%' OR LOWER(client_email) LIKE '%test%' OR LOWER(client_name) LIKE '%test%';

-- 4. reviews de teste
DELETE FROM reviews 
WHERE LOWER(client_email) LIKE '%test%' OR LOWER(client_name) LIKE '%test%' OR LOWER(vessel_name) LIKE '%test%';

-- 5. maintenances de teste
DELETE FROM maintenances 
WHERE LOWER(vessel_name) LIKE '%test%' OR LOWER(description) LIKE '%test%';

-- 6. asaas_customers de teste
DELETE FROM asaas_customers 
WHERE LOWER(client_email) LIKE '%test%' OR LOWER(name) LIKE '%test%';

-- 7. bookings de teste (por vessel_name)
DELETE FROM bookings 
WHERE LOWER(vessel_name) LIKE '%test%';

